)

var (
	noColorFlag   bool
	changeDirFlag string
)

var rootCmd = &cobra.Command{
	Use:           "intropy",
	Short:         "Intropy CLI",
	Long:          "intropy is the command-line interface for working with Intropy integrations.",
	Version:       version,
	SilenceUsage:  true,
	SilenceErrors: true,
	PersistentPreRunE: func(cmd *cobra.Command, args []string) error {
		if changeDirFlag == "" {
			return nil
		}
		if err := os.Chdir(changeDirFlag); err != nil {
			return fmt.Errorf("cannot change to directory %q: %w", changeDirFlag, err)
		}
		return nil
	},
}

func Execute() error {
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(rootCmd.ErrOrStderr(), "error:", err)
		return err
	}
	return nil
}

// validateOutputFlag returns a usageError if the given format is not in the
// allowed set. Use this for --output flags that accept a fixed list of formats.
func validateOutputFlag(format string, allowed ...string) error {
	for _, a := range allowed {
		if format == a {
			return nil
		}
	}
	return newUsageErrorf("invalid output format %q (allowed: %v)", format, allowed)
}

func init() {
	rootCmd.PersistentFlags().BoolVar(&noColorFlag, "no-color", false, "disable colored output")
	rootCmd.PersistentFlags().StringVarP(&changeDirFlag, "directory", "C", "", "change to directory before running the command")
	_ = rootCmd.MarkPersistentFlagDirname("directory")
}

package main

import (
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/integrio-intropy/intropy-cli/internal/dashboard"
	"github.com/spf13/cobra"
)

// dashboard serves the local integration dashboard. The HTTP server and
// JSON API live in internal/dashboard; this file is flag plumbing.
type dashboardFlags struct {
	port            int
	noBrowser       bool
	templateVersion string
}

var dashboardOpts dashboardFlags

var dashboardCmd = &cobra.Command{
	Use:   "dashboard [dir]",
	Short: "Launch the local integration dashboard",
	Long: "Start a local web dashboard that visualizes the integrations and systems scaffolded under dir " +
		"(default: the current directory) — their template, pinned source, version, scaffold values and " +
		"system topology. The dashboard is served from the CLI itself and opens in your browser; it does " +
		"not start any integration processes. Press Ctrl+C to stop.",
	Args: cobra.MaximumNArgs(1),
	RunE: func(cmd *cobra.Command, args []string) error {
		root := "."
		if len(args) == 1 {
			root = args[0]
		}
		if info, err := os.Stat(root); err != nil {
			return fmt.Errorf("dashboard: %w", err)
		} else if !info.IsDir() {
			return newUsageErrorf("dashboard: %s is not a directory", root)
		}

		ctx, cancel := signal.NotifyContext(cmd.Context(), os.Interrupt, syscall.SIGTERM)
		defer cancel()

		return dashboard.Serve(ctx, dashboard.Options{
			Root:            root,
			Addr:            "127.0.0.1",
			Port:            dashboardOpts.port,
			OpenBrowser:     !dashboardOpts.noBrowser,
			Version:         version,
			TemplateVersion: dashboardOpts.templateVersion,
			Stdout:          cmd.OutOrStdout(),
			Stderr:          cmd.ErrOrStderr(),
		})
	},
}

func init() {
	f := dashboardCmd.Flags()
	f.IntVarP(&dashboardOpts.port, "port", "p", 8730, "port to bind (0 picks a free port)")
	f.BoolVar(&dashboardOpts.noBrowser, "no-browser", false, "do not open the dashboard in a browser")
	f.StringVar(&dashboardOpts.templateVersion, "template-version", "", flagUsageTemplateVer)
	rootCmd.AddCommand(dashboardCmd)
}

